  const acceptEditorRules = async () => { const r = await fetch(`${API}/auth/accept-editor-rules`, { method: "POST" }); const result = await r.json().catch(() => ({})); if (!r.ok) return notify(result.detail || "No se pudieron aceptar las reglas"); setUser(result); notify("Reglas aceptadas"); };
  const logout = async () => { await fetch(`${API}/auth/logout`, { method: "POST" }); setUser(null); };
  const saveVideo = async (data, files) => { notify("Subiendo recuerdo..."); const body = new FormData(); Object.entries(data).forEach(([k, v]) => { if (v !== "" && v !== null && v !== undefined) body.append(k, Array.isArray(v) ? v.join(",") : v); }); (Array.isArray(files) ? files : [files]).forEach(file => body.append("files", file)); const r = await fetch(`${API}/videos/upload`, { method: "POST", body }); const result = await r.json().catch(() => ({})); if (!r.ok) { notify(result.detail || "No se pudo guardar el archivo"); return false; } await load(); setView("home"); notify(result.slides ? `${result.slides} slides subidos correctamente` : "Recuerdo subido correctamente"); return true; };
  const saveSticker = async (data, file) => { const body = new FormData(); body.append("title", data.title); body.append("people", data.people.join(",")); body.append("file", file); const r = await fetch(`${API}/stickers/upload`, { method: "POST", body }); const result = await r.json().catch(() => ({})); if (!r.ok) return notify(result.detail || "No se pudo guardar el sticker"); await load(); notify("Sticker guardado"); };
  const updateSticker = async (id, data) => { const r = await fetch(`${API}/stickers/${id}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(data) }); const result = await r.json().catch(() => ({})); if (!r.ok) return notify(result.detail || "No se pudo modificar el sticker"); await load(); notify("Sticker modificado"); return result; };
  const saveAlbum = async data => { const r = await fetch(`${API}/albums`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(data) }); const result = await r.json().catch(() => ({})); if (!r.ok) return notify(Array.isArray(result.detail) ? result.detail.map(item => item.msg).join(". ") : result.detail || "No se pudo crear el álbum"); await load(); notify("Álbum creado"); };
  const updateAlbum = async (id, data) => { const r = await fetch(`${API}/albums/${id}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(data) }); if (!r.ok) return notify("No se pudo modificar el álbum"); await load(); setEditingAlbum(null); notify("Álbum modificado"); };
  const saveCalendarEvent = async data => { const r = await fetch(`${API}/calendar-events`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(data) }); const result = await r.json().catch(() => ({})); if (!r.ok) return notify(result.detail || "No se pudo crear el evento"); await load(); notify("Evento agregado"); };
  const updateCalendarEvent = async (id, data) => { const r = await fetch(`${API}/calendar-events/${id}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(data) }); const result = await r.json().catch(() => ({})); if (!r.ok) return notify(result.detail || "No se pudo modificar el evento"); await load(); notify("Evento modificado"); };
