  const deleteItem = async (path, message) => { if (!window.confirm(message)) return; const r = await fetch(`${API}${path}`, { method: "DELETE" }); const result = await r.json().catch(() => ({})); if (!r.ok) return notify(result.detail || "No se pudo eliminar"); await load(); notify("Eliminado correctamente"); };
  const createPerson = async name => { const r = await fetch(`${API}/people`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name }) }); const result = await r.json(); if (!r.ok) { notify(result.detail || "No se pudo agregar la persona"); return null; } await load(); return result; };
  const createCategory = async name => { const r = await fetch(`${API}/categories`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name }) }); const result = await r.json(); if (!r.ok) { notify(result.detail || "No se pudo agregar el tipo de evento"); return null; } await load(); return result; };
  const navigate = nextView => { setView(nextView); setMobileMenuOpen(false); };
  const randomVideos = [...groupSlides(videos.filter(video => !video.albumId)), ...albums.map(album => album.videos?.length ? { ...album.videos[0], title: album.title, slides: album.videos } : album)];
  return <div className="app"><aside className={`sidebar ${mobileMenuOpen ? "mobile-open" : ""}`}><div className="brand"><img className="brand-logo" src="/logo.png" alt="AGUIRRES" /><div><small>ARCHIVO FAMILIAR</small><strong>AGUIRRES</strong></div></div><nav><Nav icon={<HomeIcon />} text="Inicio" active={view === "home"} click={() => navigate("home")} /><Nav icon={<Archive />} text="Documentos familiares" active={view === "videos"} click={() => navigate("videos")} /><Nav icon={<CirclePlus />} text="Agregar recuerdo" active={view === "add" || view === "request"} click={() => navigate(canEdit ? "add" : "request")} />  {admin && <Nav icon={<Sticker />} text="Stickers" active={view === "stickers"} click={() => navigate("stickers")} />}<Nav icon={<CalendarDays />} text="Calendario" active={view === "calendar"} click={() => navigate("calendar")} />  <Nav icon={<Users />} text="Personas" active={view === "people"} click={() => navigate("people")} />{canEdit &&     <Nav icon={<Users />} text="Admin" active={view === "admin"} click={() => navigate("admin")} />}{admin && <><Nav icon={<Users />} text="Editores" active={view === "editors"} click={() => navigate("editors")} /><Nav icon={<Settings />} text="Scripts" active={view === "scripts"} click={() => navigate("scripts")} /></>}</nav><div className="sidebar-bottom"><div className="storage"><div className="storage-icon"><HardDrive size={17} /></div><div><b>Almacenamiento</b>  <span>{storage ? `${formatStorage(storage.usedBytes)} de ${formatStorage(storage.totalBytes)}` : "Calculando..."}</span><div className="progress"><i style={{ width: `${storagePercent}%` }} /></div></div></div></div></aside>{mobileMenuOpen && <button className="menu-backdrop" aria-label="Cerrar menú" onClick={() => setMobileMenuOpen(false)} />}<main><Header user={user} logout={logout} settings={() => navigate("settings")} openCalendar={() => navigate("calendar")} toggleMenu={() => setMobileMenuOpen(open => !open)} />{view === "home" && <Home videos={randomVideos} events={calendarEvents} user={user} admin={admin} add={() => navigate("add")} open={v => setSelected(v)} />  }{view === "videos" && <Videos videos={videos} categories={categories} albums={albums} admin={admin} remove={deleteItem} open={setSelected} editAlbum={setEditingAlbum} initialAlbum={calendarAlbum} />}{view === "calendar" &&   <CalendarPage events={calendarEvents} videos={videos} albums={albums} people={people} categories={categories} admin={admin} save={saveCalendarEvent} update={updateCalendarEvent} remove={removeCalendarEvent} open={setSelected} openAlbum={album => { setCalendarAlbum(album); setView("videos"); }} />  }{view === "add" && (canEdit ? editorRulesAccepted ? <div className="content"><Title eyebrow="CREAR RECUERDO" title="Agregar recuerdo" sub="Guarda una nueva historia o crea un álbum familiar." />    <AlbumForm people={people} categories={categories} save={saveAlbum} /><VideoForm categories={categories} people={people} users={users} albums={albums} save={saveVideo} addPerson={createPerson} addCategory={createCategory} reload={load} admin={admin} /></div> : <EditorRules onAccept={acceptEditorRules} /> : <RequestAccess user={user} />)    }{view === "request" && <RequestAccess user={user} />  }{view === "stickers" && admin && <Stickers stickers={stickers} people={people} user={user} save={saveSticker} update={updateSticker} remove={deleteItem} />}  {  view === "admin" && canEdit && <AdminPage user={user} users={users} invitations={invitations} categories={categories} people={people} albums={albums} reload={load} remove={deleteItem} />}{view === "editors" && admin && <Editors editors={editors} open={setSelected} />}{view === "scripts" && admin && <Scripts />}{view === "people" && <People admin={admin} canEdit={canEdit} people={people} reload={load} open={setSelected} remove={deleteItem} />}{view === "settings" && <SettingsPage user={user} admin={admin} users={users} categories={categories} people={people} albums={albums} reload={load} saved={setUser} invitations={invitations} remove={deleteItem} />}</main>{selected &&     <Player video={selected} people={people} admin={admin || selected.createdBy === user.id || (user.role === "editor" && user.canModifyAdminMemories)} isAdmin={admin} close={() => setSelected(null)}   edit={current => { setEditing({ video: selected, targetId: current.id }); setSelected(null); }} />}{editing &&   <EditVideo2 video={editing.video} targetId={editing.targetId} categories={categories} people={people} users={users} albums={albums} close={() => setEditing(null)} saved={async result => { setEditing(null); await load(); if (result?.pendingApproval) notify("Modificación enviada para aprobación del administrador"); }} />}{editingAlbum && <EditAlbum album={editingAlbum} categories={categories} people={people} close={() => setEditingAlbum(null)} save={updateAlbum} />}{toast && <div className="toast"><Sparkles size={16} />{toast}  </div>}</div>;
